// Priority rubric from Settings (same as Mailroom app_settings.priority_rubric); empty or invalid = default.
const PRIORITY_LEVELS = [[5, 'CRITICAL', 'priorityCritical'], [4, 'HIGH', 'priorityHigh'], [3, 'MEDIUM', 'priorityMedium'],
  [2, 'LOW', 'priorityLow'], [1, 'IGNORE', 'priorityIgnore']];
const PRIORITY_DEFAULTS = {
  priorityCritical: 'action required within roughly 24 hours, hard deadline, account security or unauthorized-access alert, payment due, legal or contractual obligation.',
  priorityHigh: 'action required but not same-day; direct personal or professional correspondence expecting a reply; work requests; appointments needing confirmation.',
  priorityMedium: 'worth keeping as a record but no action needed: receipts, order and delivery confirmations, already-booked appointments, official documents.',
  priorityLow: 'informational only, mildly relevant: newsletters on subscribed topics, job postings, community or event announcements.',
  priorityIgnore: 'marketing, promotions, cold sales outreach, spam, routine automated notifications with no informational value.',
  priorityRules: 'judge priority by what the email actually demands of the recipient, not by how urgent the sender claims it is — promotional mail written in urgent language is still 1. A one-time passcode or login code is 5 only if it represents pending account access; an already-used or expired code is 3. Do not inflate scores: in a typical inbox most emails are 1 or 2.'
};
let settingRows = [];
try { settingRows = $('Get Model Setting').all().map((i) => i.json || {}); } catch (e) { settingRows = []; }
function prioritySetting(k) {
  const r = settingRows.find((x) => x.key === k);
  const raw = r && r.value != null ? String(r.value) : '';
  const v = k === 'priorityRules' ? raw.trim() : raw.replace(/\s+/g, ' ').trim();
  return v && v.length <= (k === 'priorityRules' ? 2000 : 600) ? v : PRIORITY_DEFAULTS[k];
}
const priorityRubric = ['STEP 2 — PRIORITY: assign every email an integer priority from 1 to 5 using this rubric:']
  .concat(PRIORITY_LEVELS.map((l) => l[0] + ' = ' + l[1] + ' — ' + prioritySetting(l[2]))).join('\n') +
  '\n\nScoring rules: ' + prioritySetting('priorityRules');

// Gmail ids per batch (size from Settings, default 10); a run with no mail still produces one (empty) batch so the recap is written.
const items = $input.all().filter((item) => item.json && item.json.id);
let BATCH_SIZE = 10;
try { const r = $('Get Model Setting').all().find((i) => i.json && i.json.key === 'recapBatchSize'); const v = parseInt(r && r.json.value, 10); if (v > 0) BATCH_SIZE = v; } catch (e) { BATCH_SIZE = 10; }
const totalCount = items.length;
const batchCount = Math.max(1, Math.ceil(totalCount / BATCH_SIZE));
const batches = [];

for (let i = 0; i < totalCount; i += BATCH_SIZE) {
  const batchItems = items.slice(i, i + BATCH_SIZE);
  const lines = batchItems.map((item, idx) => {
    const j = item.json;
    const date = j.internalDate ? new Date(Number(j.internalDate)).toISOString().slice(0, 10) : 'unknown';
    const snippet = (j.snippet || '').replace(/\s+/g, ' ').trim().slice(0, 200);
    return `${i + idx + 1}. Subject: ${j.Subject || '(no subject)'}\nFrom: ${j.From || 'unknown'}\nDate: ${date}\nSnippet: ${snippet}`;
  });
  batches.push({
    json: {
      batchIndex: batches.length + 1,
      batchCount,
      totalEmailCount: totalCount,
      emailCount: batchItems.length,
      emailList: lines.join('\n\n'),
      emailIds: batchItems.map((item) => item.json.id || ''),
      emailThreadIds: batchItems.map((item) => item.json.threadId || ''),
      priorityRubric
    }
  });
}

// Guarantee at least one item downstream even if the mailbox returned zero messages.
if (batches.length === 0) {
  batches.push({ json: { batchIndex: 1, batchCount: 1, totalEmailCount: 0, emailCount: 0, emailList: '(no emails in this batch)', emailIds: [], emailThreadIds: [], priorityRubric } });
}

return batches;

