// Port of logic.run_summary + summary_lines (used inside Format Recap Text).
function rsMs(v) {
  if (v == null || v === '') return 0;
  if (v instanceof Date) return v.getTime();
  if (typeof v === 'number') return v;
  const s = String(v);
  if (/^\d+(\.\d+)?$/.test(s)) return Math.floor(Number(s));
  const d = DateTime.fromISO(s, { zone: 'Europe/Rome' });
  return d.isValid ? d.toMillis() : 0;
}
function runSummary(processed, decisions, since, nowDT, engine) {
  const REPLY = ['none', 'pending', 'awaiting_approval', 'withdrawn'];
  const t0 = since ? rsMs(since) : 0;
  const fresh = processed.filter(function (r) { return rsMs(r.processedAt) >= t0; });
  let days = 7;
  try { const r = $('Get Model Setting').all().find(function (i) { return i.json && i.json.key === 'followUpDays'; }); const v = parseInt(r && r.json.value, 10); if (v > 0) days = v; } catch (e) { days = 7; }
  const week = nowDT.minus({ days: days }).toMillis();
  const newest = {};
  processed.forEach(function (r) {
    if (r.threadId && REPLY.indexOf(r.proposalStatus) >= 0 && rsMs(r.processedAt) >= week) {
      if (!newest[r.threadId] || (Number(r.id) || 0) > (Number(newest[r.threadId].id) || 0)) newest[r.threadId] = r;
    }
  });
  const open = Object.keys(newest).map(function (k) { return newest[k]; });
  const decNew = decisions.filter(function (d) { return rsMs(d.createdAt) >= t0; });
  const n = function (arr, f) { return arr.filter(f).length; };
  return {
    engine: engine || '', at: nowDT.toISO({ suppressMilliseconds: true }), since: String(since || ''), days: days,
    newEmails: fresh.length,
    draftsCreated: n(fresh, function (r) { return REPLY.indexOf(r.proposalStatus) >= 0; }),
    meetingProposals: n(fresh, function (r) { return r.proposalStatus === 'pending' || r.proposalStatus === 'withdrawn'; }),
    noReplyNeeded: n(fresh, function (r) { return r.proposalStatus === 'no_reply_needed'; }),
    bookingNotes: n(decNew, function (d) { return d.kind === 'meeting'; }),
    eventNotes: n(decNew, function (d) { return d.kind === 'event'; }),
    draftsReady: n(open, function (r) { return r.draftStatus === 'ready'; }),
    draftsSent: n(open, function (r) { return r.draftStatus === 'sent'; }),
    draftsDeleted: n(open, function (r) { return r.draftStatus === 'deleted'; }),
    notesWaiting: n(decisions, function (d) { return d.status === 'pending' && (d.kind === 'meeting' || d.kind === 'event'); })
  };
}
function summaryLines(s) {
  return [
    'New emails handled: ' + s.newEmails + (s.newEmails ? '' : ' (nothing new since the last run)'),
    'Reply drafts created: ' + s.draftsCreated + ' (with proposed times: ' + s.meetingProposals + ') | no reply needed: ' + s.noReplyNeeded,
    'Notes created: ' + s.bookingNotes + ' BOOK? | ' + s.eventNotes + ' event',
    'Last ' + (s.days || 7) + ' days: ' + s.draftsReady + ' drafts ready, not sent | ' + s.draftsSent + ' sent | ' + s.draftsDeleted + ' deleted, not sent | ' + s.notesWaiting + ' notes waiting for a decision'
  ];
}

const allItems = $input.all();
const LEVELS = [
  { score: 5, label: 'CRITICAL' },
  { score: 4, label: 'HIGH' },
  { score: 3, label: 'MEDIUM' },
  { score: 2, label: 'LOW' },
  { score: 1, label: 'IGNORE' }
];

// Pull the original per-batch Gmail ids (same order/index as the LLM batches) to re-attach identity.
let batchInputs = [];
try {
  batchInputs = $("Build Email Recap Payload").all();
} catch (e) {
  batchInputs = [];
}

// Pull the current Processed Sender Emails table, freshly re-fetched after this run's drafting branch.
let processedRows = [];
try {
  processedRows = $("Get All Processed Emails (For Recap)").all().map((it) => it.json);
} catch (e) {
  processedRows = [];
}
const processedById = new Map();
for (const row of processedRows) {
  if (row && row.trackedGmailId) {
    const prev = processedById.get(String(row.trackedGmailId));
    if (!prev || (Number(row.id) || 0) >= (Number(prev.id) || 0)) processedById.set(String(row.trackedGmailId), row);
  }
}
const DRAFT_LABEL = { ready: 'Draft ready, not sent', sent: 'Sent', deleted: 'Draft deleted, not sent',
  discarded: 'Discarded', superseded: 'Replaced by a newer draft' };

// Flatten all batches into one list of classified emails, re-attaching the Gmail id by position.
let rawEmails = [];
for (let b = 0; b < allItems.length; b++) {
  const out = (allItems[b].json && allItems[b].json.output) || allItems[b].json || {};
  const batchEmails = out.emails || [];
  const ids = (batchInputs[b] && batchInputs[b].json && batchInputs[b].json.emailIds) || [];
  if (!ids.length) continue;        // empty run: ignore whatever the model returned for "(no emails)"
  const threads = (batchInputs[b] && batchInputs[b].json && batchInputs[b].json.emailThreadIds) || [];
  for (let i = 0; i < batchEmails.length; i++) {
    rawEmails.push(Object.assign({}, batchEmails[i], { gmailId: ids[i] || '', threadId: threads[i] || '' }));
  }
}

const normalized = rawEmails.map((e) => {
  const processedRow = e.gmailId ? processedById.get(String(e.gmailId)) : undefined;
  let replyStatus = 'Not tracked';
  let scheduleStatus = '';
  if (processedRow) {
    const ps = processedRow.proposalStatus;
    replyStatus = ps === 'no_reply_needed' ? 'No reply needed' : (DRAFT_LABEL[String(processedRow.draftStatus || '')] || 'Drafted');
    if (ps === 'confirmed') scheduleStatus = 'Confirmed';
    else if (ps === 'pending') scheduleStatus = 'Proposed, awaiting confirmation';
    else if (ps === 'awaiting_approval') scheduleStatus = 'Awaiting your BOOK';
    else if (ps !== 'no_reply_needed' && ps !== 'withdrawn') scheduleStatus = 'N/A';
  }
  return {
    gmailId: e.gmailId || '',
    threadId: e.threadId || '',
    subject: e.subject || '(no subject)',
    from: e.from || 'unknown',
    date: e.date || 'unknown',
    summary: e.summary || '(no summary returned)',
    priorityReason: e.priorityReason || '',
    priority: Math.min(5, Math.max(1, Math.round(Number(e.priority)) || 1)),
    topic: (e.topic || 'Uncategorized').toString().trim() || 'Uncategorized',
    replyStatus,
    scheduleStatus
  };
});

const totalEmails = normalized.length;
const dateStr = $now.toFormat('dd-MM-yyyy');
const timeStr = $now.toFormat('HH:mm');

let text = '';
const boldRanges = [];

text += 'EMAIL RECAP\n';
text += 'Generated ' + dateStr + ' ' + timeStr + '  |  ' + totalEmails + ' emails\n\n';

// Run summary: what happened since the previous recap, and what is still open.
let decisions = [];
try { decisions = $('Get Decisions (Recap)').all().map((it) => it.json).filter((d) => d && d.id != null); } catch (e) { decisions = []; }
let since = '';
try { since = String(($('Get Last Recap').first().json || {}).generatedAt || ''); } catch (e) { since = ''; }
if (!since) since = $now.minus({ hours: 24 }).toISO();
const summary = runSummary(processedRows.filter((r) => r && r.trackedGmailId), decisions, since, $now, 'n8n');
const sHead = 'RUN SUMMARY  (n8n)';
boldRanges.push({ start: text.length, end: text.length + sHead.length });
text += sHead + '\n' + summaryLines(summary).map((l) => '    ' + l + '\n').join('') + '\n';

for (const level of LEVELS) {
  const emails = normalized.filter((e) => e.priority === level.score);
  if (emails.length === 0) continue;

  const header = level.label + '  (' + emails.length + ')';
  boldRanges.push({ start: text.length, end: text.length + header.length });
  text += header + '\n';

  emails.forEach((e, idx) => {
    text += '    ' + (idx + 1) + '. ' + e.subject + '\n';
    text += '        Topic: ' + e.topic + '\n';
    text += '        ' + e.summary + '\n';
    let meta = '        From: ' + e.from + '  |  Date: ' + e.date;
    if (e.priorityReason) {
      meta += '  |  Why ' + level.label + ': ' + e.priorityReason;
    }
    text += meta + '\n';
    let status = '        Reply: ' + e.replyStatus;
    if (e.scheduleStatus) {
      status += '  |  Schedule: ' + e.scheduleStatus;
    }
    text += status + '\n\n';
  });
}

if (totalEmails === 0) {
  text += '(No emails in this window.)\n';
}

// Google Docs indexes count UTF-16 code units, which is what JS string length counts.
const requests = [{ insertText: { location: { index: 1 }, text: text } }];
for (const r of boldRanges) {
  requests.push({
    updateTextStyle: {
      range: { startIndex: 1 + r.start, endIndex: 1 + r.end },
      textStyle: { bold: true },
      fields: 'bold'
    }
  });
}

return [{
  json: {
    title: 'Email Recap - ' + dateStr + ' ' + timeStr,
    content: text,
    requests: requests,
    emailCount: totalEmails,
    generatedAt: $now.toISO(),
    // Structured copy for the Mailroom app (Recaps tab), saved in Inbox Pilot Recaps.
    itemsJson: JSON.stringify(normalized),
    runJson: JSON.stringify(summary)
  }
}];
